        BackgroundColor3 = C.rail,
        BorderSizePixel = 0,
        Position = UDim2.new(1, -18, 0, 0),
        Size = UDim2.new(0, 18, 1, 0),
        ZIndex = 8,
    }, rail)
    corner(railFill, 14)

